application.css:
* { box-sizing: border-box; }

:root {
  color-scheme: light;
  --ink: #202b3c;
  --muted: #7a8596;
  --line: #e8ebf0;
  --accent: #5865f2;
  --accent-dark: #4652db;
  --soft: #f5f6ff;
  --card: #ffffff;
}

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  justify-content: center;
  align-items: center;
  padding: 32px 18px;
  background: linear-gradient(145deg, #eef1ff 0%, #f8f9fc 48%, #eaf8f5 100%);
  color: var(--ink);
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
}

.app-shell { width: 100%; max-width: 620px; }
.todo-card {
  padding: 34px;
  background: var(--card);
  border: 1px solid rgba(255,255,255,.8);
  border-radius: 24px;
  box-shadow: 0 22px 55px rgba(47, 58, 96, .12);
}
.app-header { display: flex; align-items: center; gap: 15px; margin-bottom: 30px; }
.brand-mark {
  width: 48px; height: 48px; display: grid; place-items: center;
  border-radius: 15px; background: var(--accent); color: white;
  font-size: 27px; font-weight: 800; box-shadow: 0 8px 18px rgba(88,101,242,.28);
}
.eyebrow { margin: 0 0 3px; color: var(--accent); font-size: 11px; font-weight: 800; letter-spacing: .12em; text-transform: uppercase; }
h1, h2 { margin: 0; } h1 { font-size: 27px; letter-spacing: -.04em; } h2 { font-size: 17px; }
.task-form { display: flex; gap: 10px; margin-bottom: 29px; }
.task-form input {
  min-width: 0; flex: 1; padding: 14px 16px; border: 1px solid var(--line); border-radius: 11px;
  outline: none; color: var(--ink); font: inherit; background: #fbfcfe; transition: border .2s, box-shadow .2s;
}
.task-form input:focus { border-color: var(--accent); box-shadow: 0 0 0 4px rgba(88,101,242,.12); }
.task-form button {
  border: 0; border-radius: 11px; padding: 0 19px; background: var(--accent); color: white;
  font: 700 14px inherit; cursor: pointer; transition: background .2s, transform .2s;
}
.task-form button:hover { background: var(--accent-dark); transform: translateY(-1px); }
.list-heading { display: flex; align-items: center; justify-content: space-between; margin-bottom: 13px; }
.task-count { color: var(--muted); font-size: 13px; font-weight: 600; }
.task-list { display: grid; gap: 9px; }
.task-item {
  display: flex; align-items: center; gap: 12px; min-height: 57px; padding: 9px 11px 9px 14px;
  border: 1px solid var(--line); border-radius: 13px; background: #fff; animation: appear .2s ease-out;
}
.task-item.is-complete { background: #fafaff; }
.complete-button { width: 22px; height: 22px; flex: 0 0 22px; border: 2px solid #cbd1df; border-radius: 50%; background: transparent; cursor: pointer; position: relative; }
.complete-button:hover { border-color: var(--accent); }
.is-complete .complete-button { border-color: var(--accent); background: var(--accent); }
.is-complete .complete-button::after { content: "✓"; position: absolute; inset: -2px 0 0; color: white; font-size: 14px; font-weight: 800; }
.task-text { flex: 1; overflow-wrap: anywhere; font-size: 14px; line-height: 1.4; }
.is-complete .task-text { color: var(--muted); text-decoration: line-through; }
.delete-button { border: 0; padding: 8px; color: #a1a9b8; background: transparent; cursor: pointer; font-size: 19px; line-height: 1; border-radius: 7px; }
.delete-button:hover { color: #e05262; background: #fff1f2; }
.empty-state { margin: 24px 0 2px; color: var(--muted); text-align: center; font-size: 13px; }
.footer-note { margin: 18px 0 0; color: #718096; text-align: center; font-size: 12px; }
.sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0,0,0,0); white-space: nowrap; border: 0; }
@keyframes appear { from { opacity: 0; transform: translateY(-5px); } to { opacity: 1; transform: translateY(0); } }
@media (max-width: 480px) { .todo-card { padding: 25px 18px; } .task-form button { padding: 0 14px; } }

